 const loadCaseData=useCallback(async(id:string)=>{if(!id){setEvidence([]);setEntities([]);setRelationships([]);setAiReview(null);setAgentRun(null);setAgentRunHistory([]);setResearchStatus('');return;}try{const d=await request<{data:{evidence:Evidence[];entities:Entity[];relationships:Relationship[];aiReviewHistory?:any[]}}>('/investigations/'+encodeURIComponent(id)+'/overview');setEvidence(d.data.evidence||[]);setEntities(d.data.entities||[]);setRelationships(d.data.relationships||[]);const runHistory=await request<{data:any[]}>('/investigations/'+encodeURIComponent(id)+'/agent-runs').catch(()=>({data:[]}));setAgentRunHistory(runHistory.data||[]);if(runHistory.data?.length)setAgentRun(runHistory.data[0]);const runState=await request<{data:any}>('/investigations/'+encodeURIComponent(id)+'/agent-run-status').catch(()=>({data:null}));const state=runState.data;if(state?.status==='running')setResearchStatus('RUNNING · '+(state.detail||'Investigation continues in the background.'));else if(state?.status==='interrupted')setResearchStatus('RUN INTERRUPTED · '+(state.detail||'Start a new run to continue.'));else if(state?.status==='failed')setResearchStatus('RUN FAILED · '+(state.detail||'Review the run and try again.'));else setResearchStatus('');const latest=(d.data.aiReviewHistory||[]).slice(-1)[0];if(latest?.provider)setAiProviderStatus(String(latest.provider)+' · successful review');setAiReview(latest?{...latest.result,generatedAt:latest.generatedAt,model:latest.model,provider:latest.provider,evidenceCount:latest.evidenceCount,limitations:['This is a saved AI-generated review, not an independently verified finding.','Review the original source records; the model did not independently browse or verify linked pages.']} : null);}catch(e){setError(e instanceof Error?e.message:'Unable to load investigation');}},[]);
