 const createCase=async(e:FormEvent)=>{e.preventDefault();try{const d=await request<{data:Investigation}>('/investigations',{method:'POST',body:JSON.stringify({title:caseTitle,question})});setCases(p=>[d.data,...p]);setCaseId(d.data.id);setCaseTitle('');setQuestion('');setCreateOpen(false);setTab('Intelligence Desk');notify('Investigation created. Starting automatic public-source discovery…');void runCaseResearch(d.data.id,true);}catch(e){setError(e instanceof Error?e.message:'Could not create investigation.');}};
 const deleteCase=async(item:Investigation)=>{if(!window.confirm('Permanently delete “'+item.title+'” and its saved links, connections, monitoring rules, alerts, and review history? This cannot be undone.'))return;try{await request('/investigations/'+encodeURIComponent(item.id),{method:'DELETE'});setCases(old=>old.filter(x=>x.id!==item.id));if(caseId===item.id){setCaseId('');await loadCaseData('');}notify('Investigation and its dependent records were deleted.');}catch(e){setError(e instanceof Error?e.message:'Could not delete investigation.');}};
 const deleteAllWorkspaceData=async()=>{if(!cases.length){setError('There are no investigations to delete.');return;}if(!window.confirm('Permanently delete all '+cases.length+' collections and their saved links, connections, monitoring rules, alerts, and review history? This cannot be undone. Your account will remain.'))return;if(window.prompt('Type DELETE ALL to confirm removing all workspace records.')!=='DELETE ALL')return;try{const d=await request<{data:{deletedCount:number};message:string}>('/investigations',{method:'DELETE'});try{localStorage.removeItem(HISTORY_KEY);localStorage.removeItem(SAVED_KEY);for(let i=localStorage.length-1;i>=0;i--){const k=localStorage.key(i);if(k?.startsWith('adverse-graph-layout:'))localStorage.removeItem(k);}}catch{}setCases([]);setCaseId('');setEvidence([]);setEntities([]);setRelationships([]);setSelectedEntityId('');setSearchResults([]);setSearchPlan([]);setSearchMeta(null);setHistoryGraph(null);setAiReview(null);setCrossReview(null);setClaimMap(null);setResearchGaps(null);notify('Deleted '+d.data.deletedCount+' collections and their saved records. Your account is still active.');}catch(e){setError(e instanceof Error?e.message:'Could not delete all workspace records.');}};
 const runSearch=async(e?:FormEvent)=>{e?.preventDefault();const missionQuestion=query.trim();if(missionQuestion.length<2){setError('Enter at least two characters to search.');return;}setSearching(true);setError('');let quickSearchFailed=false;try{if(searchMode!=='web'){const d=await request<{data:SearchResult[];meta:any}>('/public-search/media?q='+encodeURIComponent(missionQuestion)+'&type='+encodeURIComponent(searchMode));setSearchResults(d.data||[]);setSearchPlan([]);setSearchMeta(d.meta||null);setProviderCatalog([]);notify(d.data?.length?('Found '+d.data.length+' '+searchMode+' results from public indexes.'):'No '+searchMode+' results returned. '+((d.meta?.failedProviders||[]).map((x:any)=>x.provider).join(', ')||'Try another query.'));}else{const [d,p]=await Promise.all([request<{data:SearchResult[];meta:any}>('/public-search?q='+encodeURIComponent(missionQuestion)),request<{data:any[];meta:any}>('/search/providers').catch(()=>({data:[],meta:{}}))]);setSearchResults(d.data||[]);setSearchPlan(d.meta.queryPlan||[]);setSearchMeta(d.meta);setProviderCatalog(p.data||[]);notify('Search completed across '+(d.meta.providers||[]).join(', ')+'. '+d.meta.coverage);}}catch(e){quickSearchFailed=true;setError((e instanceof Error?e.message:'Public search provider unavailable.')+' ADVERSE will still attempt the full investigation using the providers available to your account.');}finally{setSearching(false);}try{const normalized=missionQuestion.toLocaleLowerCase();let mission=cases.find(c=>(c.question||'').trim().toLocaleLowerCase()===normalized);if(!mission){const created=await request<{data:Investigation}>('/investigations',{method:'POST',body:JSON.stringify({title:missionQuestion.length>72?missionQuestion.slice(0,69)+'…':missionQuestion,question:missionQuestion})});mission=created.data;setCases(old=>[mission!,...old.filter(c=>c.id!==mission!.id)]);}setCaseId(mission.id);setTab('Intelligence Desk');setAgentRun(null);setResearchStatus('SEARCH RECEIVED · Preparing the autonomous investigation…');const current=await request<{data:any}>('/investigations/'+encodeURIComponent(mission.id)+'/agent-run-status').catch(()=>({data:null}));if(current.data?.status==='running'){setResearchStatus('INVESTIGATION RUNNING · ADVERSE is already following leads for this question.');notify('This question is already being investigated. Its progress is available in IntelliDesk.');return;}notify('Search received. ADVERSE is now investigating automatically — no second action needed.');const report=await runCaseResearch(mission.id,true);if(report){setAgentRun(report);await loadCaseData(mission.id);setTab('Intelligence Desk');notify('Automatic investigation complete: '+report.queries?.length+' searches, '+report.savedCount+' new sources saved, '+report.scrapedCount+' pages retrieved, '+(report.challengeSummary?.possibleConflictCount??report.claimAnalysis?.claims?.reduce((sum:number,claim:any)=>sum+(claim.possibleConflicts||[]).length,0)??0)+' possible claim discrepancies flagged for review.');}else if(!quickSearchFailed){setError('The initial search worked, but the autonomous investigation did not complete. Check the run status and try again.');}}catch(e){setError(e instanceof Error?e.message:'Could not start the automatic investigation.');}};
 const saveResult=async(item:SearchResult)=>{if(!caseId){setError('Create or select a collection before saving a link.');return;}try{await request('/investigations/'+encodeURIComponent(caseId)+'/search/save',{method:'POST',body:JSON.stringify({title:item.title,url:item.url,excerpt:item.excerpt,publisher:item.publisher})});await loadCaseData(caseId);notify('Source saved to the selected investigation.');}catch(e){setError(e instanceof Error?e.message:'Could not save source.');}};
 const discoverCase=async(id:string)=>{await request<{data:{runId:string;status:string}}>('/investigations/'+encodeURIComponent(id)+'/agent-run',{method:'POST',body:JSON.stringify({})});const startedAt=Date.now();while(Date.now()-startedAt<180000){await new Promise(resolve=>window.setTimeout(resolve,1200));const status=await request<{data:any}>('/investigations/'+encodeURIComponent(id)+'/agent-run-status');if(status.data.status==='complete'&&status.data.report)return {data:status.data.report};if(['failed','interrupted','cancelled'].includes(status.data.status))throw new Error(status.data.detail||'Autonomous investigation stopped before completion. Review the run status and start it again when ready.');}throw new Error('This investigation is still running in the background. Reopen the collection shortly to view its saved report.');};
 const runCaseResearch=async(id:string,quiet=false)=>{if(!id){setError('Select a case before researching it.');return;}setResearching(true);setResearchStatus('Agent planning searches and collecting public-source leads…');setError('');try{const d=await discoverCase(id);setAgentRun(d.data);if(caseId===id)await loadCaseData(id);setResearchStatus('');if(!quiet)notify('Agent investigation complete: '+d.data.rounds+' research passes, '+d.data.queries.length+' queries, '+d.data.savedCount+' new sources saved and '+d.data.scrapedCount+' pages retrieved. '+d.data.leads.length+' follow-up leads explored. '+(d.data.providerFailures?'Some providers were unavailable. ':'')+'All records remain unverified.');return d.data;}catch(e){const message=e instanceof Error?e.message:'Autonomous investigation failed.';if(/cancelled by the user/i.test(message)){setResearchStatus('RUN CANCELLED · Saved source records were preserved.');if(!quiet)notify('Investigation cancelled. Saved source records were preserved.');}else{setResearchStatus('');if(!quiet)setError(message);}return null;}finally{setResearching(false);}};
 const cancelCaseResearch=async(id:string)=>{if(!id)return;try{await request('/investigations/'+encodeURIComponent(id)+'/agent-run/cancel',{method:'POST',body:JSON.stringify({})});setResearchStatus('CANCEL REQUESTED · Waiting for the current step to stop.');notify('Cancellation requested. Work already saved will remain in the investigation.');}catch(e){setError(e instanceof Error?e.message:'Could not cancel this run. Refresh the investigation status.');}};
 const researchAllCases=async()=>{if(!cases.length){setError('Create a collection before finding more sources.');return;}setResearching(true);setError('');let saved=0,scraped=0,failed=0;for(let i=0;i<cases.length;i++){const item=cases[i];setResearchStatus('Agent researching case '+(i+1)+' of '+cases.length+': '+item.title);try{const d=await discoverCase(item.id);saved+=d.data.savedCount;scraped+=d.data.scrapedCount;}catch{failed++;}}setResearchStatus('');await loadCases();if(caseId)await loadCaseData(caseId);setResearching(false);notify('Batch agent run complete: '+saved+' new evidence records, '+scraped+' pages retrieved, '+failed+' cases with provider errors. Discovered records remain unverified.');};
 const lookupArchive=async(e:FormEvent)=>{e.preventDefault();setArchiveNote('Looking up archive captures…');setError('');try{const d=await request<{data:{captures:Capture[];coverage:string}}>('/archives?url='+encodeURIComponent(archiveUrl));setCaptures(d.data.captures||[]);setArchiveNote(d.data.coverage);}catch(e){setArchiveNote('');setError(e instanceof Error?e.message:'Archive lookup failed.');}};
 const loadHistoricalGraph=async(e:FormEvent)=>{e.preventDefault();if(!caseId){setError('Select a collection before reconstructing its recorded history.');return;}if(!historyAsOf){setError('Choose a date and time for the historical view.');return;}setHistoryLoading(true);setError('');try{const asOf=new Date(historyAsOf).toISOString();const d=await request<{data:any;meta:any}>('/investigations/'+encodeURIComponent(caseId)+'/history/graph?asOf='+encodeURIComponent(asOf));setHistoryGraph(d);setSelectedEntityId('');notify('Historical graph reconstructed from records known by '+new Date(asOf).toLocaleString()+'.');}catch(e){setError(e instanceof Error?e.message:'Historical graph reconstruction failed.');}finally{setHistoryLoading(false);}};
 const compareCaptures=async()=>{if(!archiveUrl||!compareFrom||!compareTo||compareFrom===compareTo){setError('Choose two different archived captures to compare.');return;}setDiffData(null);try{const d=await request<{data:{added:string[];removed:string[];method:string;limitation:string}}>('/archives/compare?url='+encodeURIComponent(archiveUrl)+'&from='+encodeURIComponent(compareFrom)+'&to='+encodeURIComponent(compareTo));setDiffData(d.data);notify('Text comparison completed. Review the limitations before drawing conclusions.');}catch(e){setError(e instanceof Error?e.message:'Could not compare archived captures.');}};
 const searchOrganizations=async(e:FormEvent)=>{e.preventDefault();if(orgQuery.trim().length<2){setError('Enter at least two characters for organization search.');return;}setOrgSearching(true);try{const d=await request<{data:any[];meta:any}>('/organizations/search?q='+encodeURIComponent(orgQuery));setOrgResults(d.data||[]);notify('Organization search via '+d.meta.provider+'. Source attribution is retained.');}catch(e){setError(e instanceof Error?e.message:'Organization provider unavailable.');setOrgResults([]);}finally{setOrgSearching(false);}};
 const lookupDomain=async(e:FormEvent)=>{e.preventDefault();setDomainData(null);setError('');try{const d=await request<{data:any}>('/domains?url='+encodeURIComponent(domainUrl));setDomainData(d.data);}catch(e){setError(e instanceof Error?e.message:'Domain lookup failed.');}};
 const addEvidence=async(e:FormEvent)=>{e.preventDefault();if(!caseId){setError('Create or select a collection first.');return;}try{await request('/investigations/'+encodeURIComponent(caseId)+'/evidence',{method:'POST',body:JSON.stringify({title:evTitle,url:evUrl,excerpt:evExcerpt,sourceType:'manual',publisher:'User supplied',verificationStatus:'unverified'})});setEvOpen(false);setEvTitle('');setEvUrl('');setEvExcerpt('');await loadCaseData(caseId);notify('Evidence saved as unverified.');}catch(e){setError(e instanceof Error?e.message:'Could not add evidence.');}};
 const addEntity=async(e:FormEvent)=>{e.preventDefault();if(!caseId){setError('Create or select a collection first.');return;}try{await request('/investigations/'+encodeURIComponent(caseId)+'/entities',{method:'POST',body:JSON.stringify({name:entityName,type:entityType,canonicalUrl:entityUrl,description:'',evidenceIds:[]})});setEntityOpen(false);setEntityName('');setEntityUrl('');await loadCaseData(caseId);notify('Entity created. Add source-backed relationships next.');}catch(e){setError(e instanceof Error?e.message:'Could not create entity.');}};
 const addRelationship=async(e:FormEvent)=>{e.preventDefault();if(!caseId)return;try{await request('/investigations/'+encodeURIComponent(caseId)+'/relationships',{method:'POST',body:JSON.stringify({fromEntityId:relFrom,toEntityId:relTo,type:relType,evidenceIds:[relEvidence],confidence:'low',rationale:'Relationship entered by researcher; review the attached source.',verificationStatus:'unverified'})});setRelOpen(false);await loadCaseData(caseId);notify('Relationship saved with evidence provenance.');}catch(e){setError(e instanceof Error?e.message:'Could not create relationship.');}};
 const deleteEvidence=async(item:Evidence)=>{if(!window.confirm('Delete this saved evidence record? Any linked evidence references will also be removed.'))return;try{await request('/evidence/'+encodeURIComponent(key(item)),{method:'DELETE'});await loadCaseData(caseId);notify('Evidence record deleted.');}catch(e){setError(e instanceof Error?e.message:'Could not delete evidence.');}};
 const deleteEntity=async(item:Entity)=>{if(!window.confirm('Delete “'+item.name+'” and all relationships connected to it?'))return;try{await request('/investigations/'+encodeURIComponent(caseId)+'/entities/'+encodeURIComponent(key(item)),{method:'DELETE'});setSelectedEntityId('');await loadCaseData(caseId);notify('Entity and connected relationships deleted.');}catch(e){setError(e instanceof Error?e.message:'Could not delete entity.');}};
 const deleteRelationship=async(item:Relationship)=>{if(!window.confirm('Delete this documented relationship?'))return;try{await request('/investigations/'+encodeURIComponent(caseId)+'/relationships/'+encodeURIComponent(key(item)),{method:'DELETE'});await loadCaseData(caseId);notify('Relationship deleted.');}catch(e){setError(e instanceof Error?e.message:'Could not delete relationship.');}};
 const deleteAccount=async()=>{if(!window.confirm('Permanently delete your ADVERSE account and its saved information? This cannot be undone.'))return;if(window.prompt('Type DELETE to confirm permanent account and data deletion.')!=='DELETE')return;try{await request('/auth/account',{method:'DELETE'});try{localStorage.removeItem(HISTORY_KEY);localStorage.removeItem(SAVED_KEY);for(let i=localStorage.length-1;i>=0;i--){const k=localStorage.key(i);if(k?.startsWith('adverse-graph-layout:'))localStorage.removeItem(k);}}catch{}setAuthState('anonymous');setShowAuth(true);setAuthMode('login');setCases([]);setCaseId('');setEvidence([]);setEntities([]);setRelationships([]);setUserEmail('');setTab('Overview');notify('Account and associated server-side records deleted.');}catch(e){setError(e instanceof Error?e.message:'Could not delete account.');}};
 const downloadReport=async()=>{if(!caseId){setError('Select a collection to export.');return;}window.open(API+'/investigations/'+encodeURIComponent(caseId)+'/export?format='+reportFormat,'_blank','noopener,noreferrer');};
 useEffect(()=>{if(tab==='Settings'&&authState==='authenticated'){void loadProviderCredentials();void loadAiCredentials();}},[tab,authState]);
 const nav:{label:string;items:Tab[];icons:any[]}[]=[{label:'OPERATIONS',items:['Overview','Investigations','Intelligence Desk'],icons:[Activity,Layers3,Search]},{label:'INTELLIGENCE',items:['Evidence vault','Evidence graph','Time machine','Cross-source review'],icons:[Database,Waypoints,Clock3,GitBranch]},{label:'SYSTEMS',items:['Monitoring','Cyber intelligence','Integrations','Settings'],icons:[Bell,Radar,Globe2,Settings2]}];
 const tabLabels:Partial<Record<Tab,string>>={Overview:'Command center',Investigations:'Investigations','Intelligence Desk':'Live intelligence','Evidence vault':'Source archive','Evidence graph':'Connection map','Time machine':'Historical records','Cross-source review':'Claim analysis',Monitoring:'Watchlists','Cyber intelligence':'Surface scan',Integrations:'Data sources',Settings:'System settings'};
