type PublicSearchResult={title:string;url:string;excerpt:string;publisher?:string;provider?:string;providers?:string[];publishedAt?:string|null;linkCheck?:{status:'reachable'|'not_confirmed'|'not_checked';checkedAt?:string|null;note?:string};linkSignals?:{transport:string;hostname:string;signals:string[]}};
type SearchHistoryEntry={query:string;searchedAt:string;resultCount:number};
const HISTORY_KEY='adverse.find-anything.history.v1';
const SAVED_KEY='adverse.find-anything.saved.v1';
function readLocal<T>(key:string,fallback:T):T{try{const raw=localStorage.getItem(key);return raw?JSON.parse(raw) as T:fallback;}catch{return fallback;}}
function PublicSearchScreen({onSignIn}:{onSignIn:()=>void}){
 const [query,setQuery]=useState(''),[results,setResults]=useState<PublicSearchResult[]>([]),[meta,setMeta]=useState<any>(null),[loading,setLoading]=useState(false),[error,setError]=useState('');
 const [history,setHistory]=useState<SearchHistoryEntry[]>(()=>readLocal(HISTORY_KEY,[])),[saved,setSaved]=useState<PublicSearchResult[]>(()=>readLocal(SAVED_KEY,[]));
 const [filter,setFilter]=useState<'all'|'reachable'|'not_confirmed'|'not_checked'>('all'),[providerFilter,setProviderFilter]=useState('all'),[showHistory,setShowHistory]=useState(false),[showSaved,setShowSaved]=useState(false);
 const examples=['Best free coding courses','Official Nigerian university admission portal','Python documentation','How to renew a passport'];
 useEffect(()=>{try{localStorage.setItem(HISTORY_KEY,JSON.stringify(history.slice(0,12)));}catch{}},[history]);
 useEffect(()=>{try{localStorage.setItem(SAVED_KEY,JSON.stringify(saved.slice(0,100)));}catch{}},[saved]);
 const search=async(e?:FormEvent,override?:string)=>{e?.preventDefault();const q=(override??query).trim();if(q.length<2){setError('Type at least two characters to search.');return;}setQuery(q);setLoading(true);setError('');setMeta(null);setFilter('all');setProviderFilter('all');try{const response=await fetch(API+'/public-search?q='+encodeURIComponent(q),{credentials:'omit',headers:{Accept:'application/json'}});const body=await response.json();if(!response.ok)throw new Error(body?.error?.message||'Search is temporarily unavailable.');const found=(body.data||[]) as PublicSearchResult[];setResults(found);setMeta(body.meta||null);setHistory(old=>[{query:q,searchedAt:new Date().toISOString(),resultCount:found.length},...old.filter(x=>x.query.toLowerCase()!==q.toLowerCase())].slice(0,12));if(!found.length)setError(body.meta?.failedSearches?'The available search providers did not return results this time. Try again or change the wording.':'No results came back from the available public sources. Try a more specific query.');}catch(e){setResults([]);setError(e instanceof Error?e.message:'Could not search right now.');}finally{setLoading(false);}};
 const isSaved=(r:PublicSearchResult)=>saved.some(x=>x.url===r.url);
 const toggleSaved=(r:PublicSearchResult)=>setSaved(old=>old.some(x=>x.url===r.url)?old.filter(x=>x.url!==r.url):[{...r},...old].slice(0,100));
 const providers=[...new Set(results.flatMap(r=>r.providers?.length?r.providers:[r.provider||r.publisher||'Public source']))];
 const visible=results.filter(r=>(filter==='all'||(r.linkCheck?.status||'not_checked')===filter)&&(providerFilter==='all'||(r.providers?.length?r.providers:[r.provider||r.publisher||'Public source']).includes(providerFilter)));
 const summary=(r:PublicSearchResult)=>{const text=(r.excerpt||'').replace(/\s+/g,' ').trim();if(!text)return 'No preview was supplied by this source. Open the original page to inspect it.';const first=text.split(/(?<=[.!?])\s+/)[0]||text;return first.length>220?first.slice(0,217).trimEnd()+'…':first;};
 const resultCard=(r:PublicSearchResult,i:number)=><article className="find-result-card" key={r.url||r.title}><div className="find-result-number">{String(i+1).padStart(2,'0')}</div><div className="find-result-body"><div className="find-result-source">{r.provider||r.publisher||'Public source'}{r.providers&&r.providers.length>1&&<span title={r.providers.join(", ")}> · Found by {r.providers.length} search services</span>}{r.publishedAt&&<span> · {r.publishedAt}</span>}</div><h3><a href={r.url} target="_blank" rel="noopener noreferrer">{r.title||r.url}<ExternalLink size={14}/></a></h3><p>{r.excerpt||'The source did not provide a useful preview. Open the original page to inspect its contents.'}</p><div className="find-quick-summary"><Sparkles size={13}/><span><b>Quick take:</b> {summary(r)}</span></div>{r.linkSignals&&<div className="find-domain-line"><Globe2 size={12}/><span>{r.linkSignals.hostname}</span><b>{r.linkSignals.transport}</b></div>}{Boolean(r.linkSignals?.signals?.length)&&<div className="find-link-warnings" role="note"><ShieldCheck size={13}/><span><b>Check before trusting:</b> {r.linkSignals!.signals.join(' · ')}. These are caution signals, not a malware or fraud verdict.</span></div>}<div className="find-result-foot"><span className={'find-link-status '+(r.linkCheck?.status==='reachable'?'reachable':'unconfirmed')}><span/>{r.linkCheck?.status==='reachable'?'LINK REACHABLE':r.linkCheck?.status==='not_confirmed'?'NOT CONFIRMED':'NOT CHECKED'}</span><span>{r.linkCheck?.note||'Open the original page to verify access.'}</span><button className={'find-save-button '+(isSaved(r)?'saved':'')} onClick={()=>toggleSaved(r)} aria-pressed={isSaved(r)}>{isSaved(r)?<Check size={13}/>:<Plus size={13}/>} {isSaved(r)?'Saved':'Save link'}</button><a href={r.url} target="_blank" rel="noopener noreferrer">Open original <ExternalLink size={12}/></a></div></div></article>;
 return <main className="find-anything-page"><header className="find-topbar"><a className="find-brand" href="/" aria-label="ADVERSE home"><span className="find-brand-mark"><Fingerprint size={19} strokeWidth={1.8}/></span><span>ADVERSE<small>FIND ANYTHING</small></span></a><div className="find-top-links"><span><span className="find-status-dot"/> Public search</span><button onClick={onSignIn}>Sign in</button></div></header>
 <section className="find-hero"><div className="find-eyebrow"><span className="find-status-dot"/> THE WEB, WITH LESS WASTED TIME</div><h1>Find anything.<br/><span>Skip the dead ends.</span></h1><p className="find-subtitle">Search the public web for useful pages, official resources, tools, guides, and answers. ADVERSE checks whether selected pages respond before calling them reachable.</p>
 <form className="find-search-form" onSubmit={e=>search(e)}><Search size={22}/><input value={query} onChange={e=>setQuery(e.target.value)} placeholder="What are you trying to find?" aria-label="Search anything online"/><button aria-label={loading?'Searching':'Find it'} disabled={loading} type="submit">{loading?<RefreshCw size={16} className="spin"/>:<Search size={16}/>}<span>{loading?'Searching…':'Find it'}</span></button></form>
 <div className="find-personal-tools"><button type="button" onClick={()=>{setShowHistory(x=>!x);setShowSaved(false)}} aria-expanded={showHistory}><Clock3 size={14}/> Recent searches <span>{history.length}</span></button><button type="button" onClick={()=>{setShowSaved(x=>!x);setShowHistory(false)}} aria-expanded={showSaved}><BookOpen size={14}/> Saved links <span>{saved.length}</span></button></div>
 {showHistory&&<section className="find-local-panel"><div className="find-local-panel-head"><b>Recent searches</b><button type="button" onClick={()=>{setHistory([]);setShowHistory(false)}} disabled={!history.length}>Clear history</button></div>{history.length?history.map(item=><button className="find-history-item" key={item.query} onClick={()=>search(undefined,item.query)}><Search size={13}/><span>{item.query}<small>{item.resultCount} results · {new Date(item.searchedAt).toLocaleDateString()}</small></span><ArrowUpRight size={13}/></button>):<p>Your searches will appear here on this device.</p>}</section>}
 {showSaved&&<section className="find-local-panel"><div className="find-local-panel-head"><b>Saved links</b><span>{saved.length} saved on this device</span></div>{saved.length?saved.map(r=><div className="find-saved-item" key={r.url}><div><a href={r.url} target="_blank" rel="noopener noreferrer">{r.title||r.url} <ExternalLink size={12}/></a><small>{r.provider||r.publisher||r.url}</small></div><button type="button" onClick={()=>toggleSaved(r)} aria-label={'Remove '+r.title+' from saved links'}><X size={14}/></button></div>):<p>Save a result to keep it handy on this device.</p>}</section>}
 {!results.length&&<div className="find-examples"><span>TRY SEARCHING FOR</span>{examples.map(x=><button type="button" key={x} onClick={()=>setQuery(x)}>{x}<ArrowUpRight size={13}/></button>)}</div>}
 {loading&&<div className="find-loading"><span className="find-loader"/><div><b>Finding useful pages</b><span>Searching public sources and checking a selection of links. This can take a little while.</span></div></div>}
 {error&&<div className="find-error" role="alert">{error}</div>}
 {results.length>0&&<section className="find-results"><div className="find-results-head"><div><span className="find-eyebrow">RESULTS FOR</span><h2>{query}</h2><p>{meta?.coverage||'Results from available public sources.'}</p></div><span className="find-count">{results.length} results</span></div>
 <div className="find-trust-note"><ShieldCheck size={16}/><span><b>Honest link checks.</b> “Reachable” means a public page responded during our check—not that every statement on it is true. Redirects and anti-bot restrictions may prevent verification.</span></div>
 <div className="find-result-filters"><label>Link status<select value={filter} onChange={e=>setFilter(e.target.value as typeof filter)}><option value="all">All statuses</option><option value="reachable">Reachable</option><option value="not_confirmed">Not confirmed</option><option value="not_checked">Not checked</option></select></label><label>Source<select value={providerFilter} onChange={e=>setProviderFilter(e.target.value)}><option value="all">All sources</option>{providers.map(p=><option key={p} value={p}>{p}</option>)}</select></label><span>{visible.length} shown</span></div>
 <div className="find-result-list">{visible.length?visible.map((r,i)=>resultCard(r,i)):<div className="find-no-filter-results">No results match these filters. Try a different link status or source.</div>}</div>
 <p className="find-search-meta">Checked {meta?.linkChecks||0} selected links · {meta?.successfulSearches||0} successful provider searches · {meta?.failedSearches||0} provider failures. Results may be incomplete. Search history and saved links stay in this browser unless cleared.</p>
 </section>}
 </section><footer className="find-footer"><span>ADVERSE <i>/</i> FIND ANYTHING</span><span>Public-source search · No invented destinations</span><button onClick={onSignIn}>Sign in to save your research</button></footer></main>;
}

type WatchRecord={id:string;url:string;label:string;intervalHours:number;enabled:boolean;lastCaptureTimestamp?:string;lastCheckedAt?:string|null;nextCheckAt?:string|null;lastError?:string;createdAt?:string};
type MonitorAlert={id:string;watchId:string;url?:string;label?:string;message?:string;observedAt?:string;acknowledgedAt?:string|null;previousCaptureTimestamp?:string;captureTimestamp?:string;emailStatus?:'pending'|'sent'|'disabled';emailAttempts?:number;emailLastError?:string};
function MonitoringView({cases,caseId,setCaseId,onError,onNotice}:{cases:Investigation[];caseId:string;setCaseId:(id:string)=>void;onError:(message:string)=>void;onNotice:(message:string)=>void}){
 const [watches,setWatches]=useState<WatchRecord[]>([]),[alerts,setAlerts]=useState<MonitorAlert[]>([]),[meta,setMeta]=useState<{scheduler:string;scope:string}|null>(null);
 const [url,setUrl]=useState(''),[label,setLabel]=useState(''),[intervalHours,setIntervalHours]=useState('24'),[loading,setLoading]=useState(false),[saving,setSaving]=useState(false),[checkingId,setCheckingId]=useState('');
 const load=useCallback(async()=>{if(!caseId){setWatches([]);setAlerts([]);setMeta(null);return;}setLoading(true);try{const d=await request<{data:{watches:WatchRecord[];alerts:MonitorAlert[];meta:{scheduler:string;scope:string}}}>('/investigations/'+encodeURIComponent(caseId)+'/monitoring');setWatches(d.data.watches||[]);setAlerts(d.data.alerts||[]);setMeta(d.data.meta||null);}catch(e){onError(e instanceof Error?e.message:'Could not load monitoring records.');}finally{setLoading(false);}},[caseId,onError]);
 useEffect(()=>{load();},[load]);
 const addWatch=async(e:FormEvent)=>{e.preventDefault();if(!caseId){onError('Select a collection before adding a watch.');return;}setSaving(true);try{await request('/investigations/'+encodeURIComponent(caseId)+'/monitoring',{method:'POST',body:JSON.stringify({url,label,intervalHours:Number(intervalHours)})});setUrl('');setLabel('');await load();onNotice('Monitoring rule saved. Archive checks depend on the deployed worker and provider coverage.');}catch(e){onError(e instanceof Error?e.message:'Could not save monitoring rule.');}finally{setSaving(false);}};
 const checkWatch=async(id:string)=>{setCheckingId(id);try{const d=await request<{data:{skipped?:boolean;message?:string}}>('/monitoring/'+encodeURIComponent(id)+'/check',{method:'POST'});await load();onNotice(d.data?.message||'Archive check requested.');}catch(e){onError(e instanceof Error?e.message:'Could not check this archive rule.');}finally{setCheckingId('');}};
 const removeWatch=async(id:string)=>{try{await request('/monitoring/'+encodeURIComponent(id),{method:'DELETE'});await load();onNotice('Monitoring rule removed.');}catch(e){onError(e instanceof Error?e.message:'Could not remove monitoring rule.');}};
 const acknowledge=async(id:string)=>{try{await request('/alerts/'+encodeURIComponent(id)+'/acknowledge',{method:'POST'});await load();onNotice('Alert acknowledged.');}catch(e){onError(e instanceof Error?e.message:'Could not acknowledge alert.');}};
 const removeAlert=async(id:string)=>{if(!window.confirm('Permanently delete this monitoring alert?'))return;try{await request('/alerts/'+encodeURIComponent(id),{method:'DELETE'});await load();onNotice('Alert deleted.');}catch(e){onError(e instanceof Error?e.message:'Could not delete alert.');}};
 return <section className="panel page-panel"><div className="panel-heading"><div><h2>Archive monitoring</h2><p>Save public URLs for Internet Archive capture checks. This is not continuous live-page surveillance.</p></div><button className="secondary-button" onClick={load} disabled={loading}><RefreshCw size={14} className={loading?'spin':''}/> Refresh</button></div>
 {!cases.length?<Empty title="Create a collection first" text="Your website checks are saved in a private collection."/>:<><div className="monitor-case-picker"><label>Save in collection<select value={caseId} onChange={e=>setCaseId(e.target.value)}><option value="">Choose a collection</option>{cases.map(c=><option key={c.id} value={c.id}>{c.title}</option>)}</select></label><span className="muted-tag">{watches.length}/20 RULES</span></div>
 <form className="monitor-form" onSubmit={addWatch}><label>Public URL<input type="url" required value={url} onChange={e=>setUrl(e.target.value)} placeholder="https://example.org/page"/></label><label>Display label<input value={label} onChange={e=>setLabel(e.target.value)} maxLength={160} placeholder="Optional page name"/></label><label>Check interval<select value={intervalHours} onChange={e=>setIntervalHours(e.target.value)}><option value="6">Every 6 hours</option><option value="12">Every 12 hours</option><option value="24">Every 24 hours</option></select></label><button className="primary-button" disabled={!caseId||saving||watches.length>=20}><Plus size={15}/>{saving?'Saving…':'Add watch'}</button></form>
 <div className="monitor-disclaimer"><ShieldCheck size={15}/><span>{meta?.scope||'Checks depend on the Internet Archive CDX API.'} {meta?.scheduler||'Worker scheduling depends on deployment configuration.'}</span></div>
 <div className="monitor-section-heading"><h3>Watch rules</h3><span>{watches.length} saved</span></div>{watches.length===0?<Empty title="No watch rules yet" text="Add a public URL above to create a monitoring rule."/>:<div className="watch-list">{watches.map(w=><article className="watch-row" key={w.id}><div className="watch-symbol"><Globe2 size={17}/></div><div className="watch-details"><b>{w.label||w.url}</b><a href={w.url} target="_blank" rel="noreferrer">{w.url} <ExternalLink size={12}/></a><span><Clock3 size={12}/> Every {w.intervalHours} hours · {w.enabled?'Enabled':'Disabled'} · {w.lastCheckedAt?'Last checked '+new Date(w.lastCheckedAt).toLocaleString():'Not checked yet'}</span>{w.lastError&&<small className="watch-error">{w.lastError}</small>}</div><div className="watch-actions"><button className="secondary-button" onClick={()=>checkWatch(w.id)} disabled={checkingId===w.id} aria-label={'Check now '+(w.label||w.url)}><RefreshCw size={14} className={checkingId===w.id?'spin':''}/>{checkingId===w.id?'Checking…':'Check now'}</button><button className="secondary-button" onClick={()=>removeWatch(w.id)} aria-label={'Remove watch '+(w.label||w.url)}><X size={14}/> Remove website</button></div></article>)}</div>}
 <div className="monitor-section-heading"><h3>Recent alerts</h3><span>{alerts.filter(a=>!a.acknowledgedAt).length} unacknowledged</span></div>{alerts.length===0?<Empty title="No alerts recorded" text="Alerts appear here if the configured archive-check worker records a change."/>:<div className="watch-list">{alerts.map(a=><article className="watch-row alert-row" key={a.id}><div className="watch-symbol"><Bell size={17}/></div><div className="watch-details"><b>{a.label||a.url||'Archive observation'}</b><p>{a.message||'An archive observation was recorded. Compare the capture timestamps before interpreting it.'}</p><span>{a.observedAt?new Date(a.observedAt).toLocaleString():'Observation time unavailable'} · {a.acknowledgedAt?'Acknowledged':'Needs review'}</span>{a.emailStatus&&<small className={a.emailStatus==='sent'?'email-status email-sent':'email-status'}>{a.emailStatus==='sent'?'Email sent':a.emailStatus==='pending'?'Email delivery pending · '+(a.emailAttempts||0)+' attempt(s)':'Email disabled'}</small>}{a.emailLastError&&<small className="watch-error">{a.emailLastError}</small>}{a.url&&<a href={a.url} target="_blank" rel="noreferrer">Open watched URL <ExternalLink size={12}/></a>}</div><div className="watch-actions">{!a.acknowledgedAt&&<button className="secondary-button" onClick={()=>acknowledge(a.id)}><Check size={14}/> Acknowledge</button>}<button className="secondary-button" onClick={()=>void removeAlert(a.id)} aria-label={'Delete alert '+(a.label||a.url||a.id)}><Trash2 size={14}/> Delete</button></div></article>)}</div>}</>}
 </section>;
}


type CyberAssetRecord={id:string;url:string;hostname:string;label:string;intervalHours:number;enabled:boolean;lastCheckedAt?:string|null;nextCheckAt?:string|null;lastHttpStatus?:number|null;lastError?:string;authorizedByUser?:boolean;verificationToken?:string;verificationStatus?:'pending'|'verified';verifiedAt?:string|null};
type CyberEventRecord={id:string;assetId:string;type:string;severity:string;title:string;message:string;url:string;observedAt?:string;acknowledgedAt?:string|null;details?:any};
function CyberIntelligenceView({cases,caseId,setCaseId,onError,onNotice}:{cases:Investigation[];caseId:string;setCaseId:(id:string)=>void;onError:(message:string)=>void;onNotice:(message:string)=>void}){
 const [assets,setAssets]=useState<CyberAssetRecord[]>([]),[events,setEvents]=useState<CyberEventRecord[]>([]),[meta,setMeta]=useState<any>(null);
 const [url,setUrl]=useState(''),[label,setLabel]=useState(''),[intervalHours,setIntervalHours]=useState('6'),[loading,setLoading]=useState(false),[saving,setSaving]=useState(false),[workingId,setWorkingId]=useState('');
 const load=useCallback(async()=>{if(!caseId){setAssets([]);setEvents([]);setMeta(null);return;}setLoading(true);try{const d=await request<{data:{assets:CyberAssetRecord[];events:CyberEventRecord[];meta:any}}>('/investigations/'+encodeURIComponent(caseId)+'/cyber-assets');setAssets(d.data.assets||[]);setEvents(d.data.events||[]);setMeta(d.data.meta||null);}catch(e){onError(e instanceof Error?e.message:'Could not load website monitoring details.');}finally{setLoading(false);}},[caseId,onError]);
 useEffect(()=>{load();},[load]);
 const addAsset=async(e:FormEvent)=>{e.preventDefault();if(!caseId){onError('Choose a collection first.');return;}setSaving(true);try{await request('/investigations/'+encodeURIComponent(caseId)+'/cyber-assets',{method:'POST',body:JSON.stringify({url,label,intervalHours:Number(intervalHours)})});setUrl('');setLabel('');await load();onNotice('Website added. Follow the steps below to confirm you can manage it before monitoring starts.');}catch(e){onError(e instanceof Error?e.message:'Could not add this website.');}finally{setSaving(false);}};
 const verifyDomain=async(id:string)=>{setWorkingId(id);try{const d=await request<{data:{message:string}}>('/cyber-assets/'+encodeURIComponent(id)+'/verify-domain',{method:'POST',body:JSON.stringify({})});await load();onNotice(d.data.message||'Website access confirmed.');}catch(e){onError(e instanceof Error?e.message:'Could not confirm access to this website.');}finally{setWorkingId('');}};
 const verifyHttp=async(id:string)=>{setWorkingId(id);try{const d=await request<{data:{message:string}}>('/cyber-assets/'+encodeURIComponent(id)+'/verify-http',{method:'POST',body:JSON.stringify({})});await load();onNotice(d.data.message||'Website control verified.');}catch(e){onError(e instanceof Error?e.message:'Could not confirm access to this website.');}finally{setWorkingId('');}};
 const check=async(id:string)=>{setWorkingId(id);try{const d=await request<{data:{observation?:{events?:any[];error?:string}}}>('/cyber-assets/'+encodeURIComponent(id)+'/check',{method:'POST'});await load();onNotice(d.data.observation?.error?'Check failed: '+d.data.observation.error:'Website check finished. '+(d.data.observation?.events?.length||0)+' event(s) recorded.');}catch(e){onError(e instanceof Error?e.message:'The website check could not be completed.');}finally{setWorkingId('');}};
 const remove=async(id:string)=>{setWorkingId(id);try{await request('/cyber-assets/'+encodeURIComponent(id),{method:'DELETE'});await load();onNotice('Website and its saved activity removed.');}catch(e){onError(e instanceof Error?e.message:'Could not remove this website.');}finally{setWorkingId('');}};
 return <section className="panel page-panel cyber-panel">
  <div className="panel-heading"><div><h2><Radar size={17}/> Website monitoring</h2><p>Keep track of a website you manage. Confirm you can make changes to it before monitoring begins.</p></div><button className="secondary-button" onClick={load} disabled={loading}><RefreshCw size={14} className={loading?'spin':''}/> Refresh</button></div>
  <div className="cyber-scope"><ShieldCheck size={18}/><div><b>Before you start</b><p>To make sure you can manage this website, ADVERSE asks you to add a one-time code to its settings. You can do this through your domain provider or by adding a small text file to the website. Monitoring starts only after ADVERSE finds the code. This confirms you can make changes to the site; it does not establish legal ownership.</p></div></div>
  {!cases.length?<Empty title="Create a collection first" text="Your websites are saved in the collection you choose."/>:<>
   <div className="monitor-case-picker"><label>Collection<select value={caseId} onChange={e=>setCaseId(e.target.value)}><option value="">Choose a collection</option>{cases.map(c=><option key={c.id} value={c.id}>{c.title}</option>)}</select></label><span className="muted-tag">{assets.length}/25 WEBSITES</span></div>
   <form className="cyber-form" onSubmit={addAsset}>
    <label>Website address<input type="url" required value={url} onChange={e=>setUrl(e.target.value)} placeholder="https://your-domain.example"/></label>
    <label>Website name (optional)<input value={label} onChange={e=>setLabel(e.target.value)} maxLength={160} placeholder="My website"/></label>
    <label>Check interval<select value={intervalHours} onChange={e=>setIntervalHours(e.target.value)}><option value="1">Every hour</option><option value="6">Every 6 hours</option><option value="12">Every 12 hours</option><option value="24">Every 24 hours</option></select></label>
    <button className="primary-button" disabled={!caseId||saving||assets.length>=25}><Plus size={15}/>{saving?'Adding…':'Add website'}</button>
   </form>
   <div className="cyber-metrics"><div><span>WEBSITES ADDED</span><b>{assets.length}</b></div><div><span>RECENT UPDATES</span><b>{events.length}</b></div><div><span>NEEDS YOUR ATTENTION</span><b>{events.filter(e=>!e.acknowledgedAt&&e.type!=='baseline').length}</b></div><div><span>LAST CHECK</span><b>{assets.some(a=>a.lastCheckedAt)?new Date(Math.max(...assets.filter(a=>a.lastCheckedAt).map(a=>new Date(a.lastCheckedAt!).getTime()))).toLocaleTimeString():'—'}</b></div></div>
   <div className="monitor-section-heading"><h3>Your websites</h3><span>{assets.length} added</span></div>
   {assets.length===0?<Empty title="No websites added yet" text="Add a website above. ADVERSE will show you how to confirm you control it before checks begin."/>:<div className="watch-list">{assets.map(a=><article className="watch-row cyber-asset-row" key={a.id}><div className="watch-symbol"><Server size={17}/></div><div className="watch-details"><b>{a.label||a.hostname}</b><a href={a.url} target="_blank" rel="noopener noreferrer">{a.url} <ExternalLink size={12}/></a><span><Clock3 size={12}/> Checks every {a.intervalHours===1?'hour':a.intervalHours+' hours'} · {a.lastCheckedAt?'Last checked '+new Date(a.lastCheckedAt).toLocaleString():'Not checked yet'} · {a.lastHttpStatus?'Website response '+a.lastHttpStatus:'No response recorded yet'}</span>{a.lastError&&<small className="watch-error">{a.lastError}</small>}<small className="muted-copy">{a.verificationStatus==='verified'?'Website access confirmed · monitoring on':'Not confirmed · monitoring paused'}</small>{a.verificationStatus!=='verified'&&a.verificationToken&&<div className="verification-instructions"><p><b>Option 1 — Use your domain settings:</b> Open the service where you manage this domain and add a TXT record.</p><p><b>Record name:</b> <code>{'_adverse-verification.'+a.hostname.replace(/^www\./i,'')}</code></p><p><b>Copy this code as the value:</b> <code>{'adverse-verification='+a.verificationToken}</code></p><p>Save the change. It may take a little while to become visible, then select “Check DNS record”.</p><button className="secondary-button" onClick={()=>verifyDomain(a.id)} disabled={workingId===a.id}><ShieldCheck size={14}/>{workingId===a.id?'Checking…':'Check DNS record'}</button><p><b>Option 2 — Easiest for React / Vite:</b> In your project, create <code>public/adverse-verify.txt</code>. Paste only this code into the file:</p><code>{'adverse-verification='+a.verificationToken}</code><p>Deploy your site. The file should then open at <code>{'https://'+a.hostname+'/adverse-verify.txt'}</code>. Keep the filename and code exactly as shown, then click below.</p><button className="secondary-button" onClick={()=>verifyHttp(a.id)} disabled={workingId===a.id}><ShieldCheck size={14}/>{workingId===a.id?'Checking…':'Check verification file'}</button></div>}</div><div className="watch-actions"><button className="secondary-button" onClick={()=>check(a.id)} disabled={workingId===a.id||a.verificationStatus!=='verified'}><RefreshCw size={14} className={workingId===a.id?'spin':''}/>{workingId===a.id?'Checking…':a.verificationStatus==='verified'?'Check now':'Confirm access first'}</button><button className="secondary-button" onClick={()=>remove(a.id)} disabled={workingId===a.id}><X size={14}/> Remove</button></div></article>)}</div>}
   <div className="monitor-section-heading"><h3>Recent activity</h3><span>{events.length} updates</span></div>
   {events.length===0?<Empty title="Nothing to show yet" text="After the first check, updates such as website changes, domain-setting changes, and failed checks will appear here."/>:<div className="cyber-event-list">{events.map(e=><article className="cyber-event" key={e.id}><div className={'cyber-event-mark '+(e.severity||'info')}/><div className="cyber-event-body"><div className="cyber-event-top"><b>{e.title}</b><span>{(e.severity||'info').toUpperCase()} · {(e.type||'event').replaceAll('-',' ').toUpperCase()}</span></div><p>{e.message}</p><a href={e.url} target="_blank" rel="noopener noreferrer">{e.url} <ExternalLink size={11}/></a><small>{e.observedAt?new Date(e.observedAt).toLocaleString():'Timestamp unavailable'} · Source: ADVERSE public check</small></div></article>)}</div>}
   <p className="provider-note">Automatic checks: {meta?.scheduler||'Automatic checks need a scheduled background service. Websites that have not been confirmed are skipped.'} ADVERSE checks publicly available website information only; it does not access private networks or devices.</p>
  </>}
 </section>;
}

function AuthScreen({mode,setMode,email,setEmail,password,setPassword,displayName,setDisplayName,error,message,onSubmit}:{mode:'login'|'register'|'forgot'|'reset';setMode:(m:'login'|'register'|'forgot'|'reset')=>void;email:string;setEmail:(v:string)=>void;password:string;setPassword:(v:string)=>void;displayName:string;setDisplayName:(v:string)=>void;error:string;message:string;onSubmit:(e:FormEvent)=>void}){const isLogin=mode==='login',isRegister=mode==='register',isForgot=mode==='forgot',isReset=mode==='reset';return <div className="auth-shell"><form className="auth-card" onSubmit={onSubmit}><div className="auth-brand"><div className="brand-mark"><Fingerprint size={23}/></div><span>PUBLIC INTELLIGENCE WORKSPACE</span></div><span className="eyebrow"><span className="live-dot"/> SECURE RESEARCH ENVIRONMENT</span><h1>{isLogin?'Welcome back.':isRegister?'Create your workspace.':isForgot?'Recover your account.':'Choose a new password.'}</h1><p>{isLogin?'Sign in to reopen your investigations and evidence.':isRegister?'Create an account to keep your investigations private to you.':isForgot?'Enter your account email. If an account exists, we will send a secure reset link.':'Choose a strong password of at least 12 characters. This reset link can only be used once.'}</p>{error&&<div className="notice error-notice" role="alert">{error}</div>}{message&&<div className="notice success-notice" role="status">{message}</div>}{isRegister&&<label>Display name<input value={displayName} onChange={e=>setDisplayName(e.target.value)} maxLength={80} required placeholder="Researcher name"/></label>}{!isReset&&<label>Email address<input type="email" autoComplete="email" value={email} onChange={e=>setEmail(e.target.value)} required maxLength={254} placeholder="you@example.com" disabled={isReset}/></label>}{!isForgot&&<label>{isReset?'New password':'Password'}<input type="password" autoComplete={isLogin?'current-password':'new-password'} value={password} onChange={e=>setPassword(e.target.value)} required minLength={12} maxLength={128} placeholder="At least 12 characters"/></label>}{isRegister&&<small className="auth-security"><ShieldCheck size={14}/> Passwords are hashed server-side; sessions use HttpOnly cookies.</small>}<button className="primary-button auth-submit">{isLogin?'Sign in':isRegister?'Create account':isForgot?'Send reset link':'Update password'} <ArrowUpRight size={16}/></button>{isLogin&&<button type="button" className="auth-link-button" onClick={()=>setMode('forgot')}>Forgot password?</button>}{isForgot||isReset?<div className="auth-toggle"><button type="button" onClick={()=>setMode('login')}>Back to sign in</button></div>:<div className="auth-toggle">{isLogin?'New to ADVERSE?':'Already have an account?'} <button type="button" onClick={()=>setMode(isLogin?'register':'login')}>{isLogin?'Create account':'Sign in'}</button></div>}<div className="auth-footer"><ShieldCheck size={14}/> Evidence before conclusions. Privacy by ownership.</div></form></div>}
function Empty({title,text,action}:{title:string;text:string;action?:()=>void}){return <div className="empty-state"><div className="empty-icon"><FileSearch size={22}/></div><b>{title}</b><p>{text}</p>{action&&<button className="secondary-button" onClick={action}><Plus size={15}/> Get started</button>}</div>}
function Modal({title,kicker,onClose,children}:{title:string;kicker:string;onClose:()=>void;children:any}){return <div className="modal-backdrop" onMouseDown={e=>{if(e.target===e.currentTarget)onClose();}}><section className="modal"><div className="modal-heading"><div><span className="eyebrow">{kicker}</span><h2>{title}</h2></div><button type="button" className="icon-button" onClick={onClose} aria-label="Close"><X size={18}/></button></div>{children}</section></div>}
const ForceGraph2DComponent = ForceGraph2D as any;
function Graph({entities,relationships,onSelect,selectedId,query,layoutKey}:{entities:Entity[];relationships:Relationship[];onSelect:(entity:Entity)=>void;selectedId:string;query:string;layoutKey:string}){
 const [relationshipFilter,setRelationshipFilter]=useState('all');
 const [selectedRelationshipId,setSelectedRelationshipId]=useState('');
 const [graphSize,setGraphSize]=useState({width:800,height:420});
 const graphRef=useRef<any>(null);
 const visible=entities.filter(e=>(e.name+' '+e.type+' '+e.description).toLowerCase().includes(query.trim().toLowerCase()));
 const visibleIds=new Set(visible.map(key));
 const relationshipTypes=[...new Set(relationships.map(r=>r.type))].sort();
 const visibleRelations=relationships.filter(r=>visibleIds.has(r.fromEntityId)&&visibleIds.has(r.toEntityId)&&(relationshipFilter==='all'||r.type===relationshipFilter));
 const graphData=useMemo(()=>({
  nodes:visible.map(e=>({id:key(e),name:e.name,type:e.type,description:e.description,evidenceIds:e.evidenceIds||[]})),
  links:visibleRelations.map((r,i)=>({id:key(r)||r.fromEntityId+'-'+r.toEntityId+'-'+i,source:r.fromEntityId,target:r.toEntityId,type:r.type,confidence:r.confidence,verificationStatus:r.verificationStatus,evidenceIds:r.evidenceIds||[],rationale:r.rationale}))
 }),[visible,visibleRelations]);
 useEffect(()=>{const resize=()=>setGraphSize({width:Math.max(320,Math.min(1200,document.documentElement.clientWidth-64)),height:420});resize();window.addEventListener('resize',resize);return()=>window.removeEventListener('resize',resize);},[]);
 useEffect(()=>{if(!graphData.nodes.length)return;const frame=requestAnimationFrame(()=>graphRef.current?.zoomToFit?.(500,70));return()=>cancelAnimationFrame(frame);},[graphData.nodes.length,graphData.links.length]);
 const selectedRelationship=visibleRelations.find((r,i)=>(key(r)||r.fromEntityId+'-'+r.toEntityId+'-'+i)===selectedRelationshipId);
 if(!entities.length)return <div className="graph-preview graph-empty"><Network size={24}/><b>No entities in this case</b><span>Add entities in the graph view to begin mapping documented connections.</span></div>;
 if(!visible.length)return <div className="graph-preview graph-empty"><Search size={22}/><b>No matching entities</b><span>Try another name, entity type, or description.</span></div>;
 const resetView=()=>graphRef.current?.zoomToFit?.(500,70);
 const saveLayout=()=>{const positions=Object.fromEntries(graphData.nodes.map(n=>[String(n.id),{x:(n as any).x,y:(n as any).y}]));try{localStorage.setItem('adverse-graph-layout:'+layoutKey,JSON.stringify(positions));}catch{}};
 const restoreLayout=()=>{try{const raw=localStorage.getItem('adverse-graph-layout:'+layoutKey);const saved=raw?JSON.parse(raw):{};graphData.nodes.forEach(n=>{const p=saved[String(n.id)];if(p&&Number.isFinite(p.x)&&Number.isFinite(p.y)){(n as any).x=p.x;(n as any).y=p.y;}});graphRef.current?.d3ReheatSimulation?.();resetView();}catch{}};
 const clearLayout=()=>{try{localStorage.removeItem('adverse-graph-layout:'+layoutKey);}catch{}graphData.nodes.forEach(n=>{delete (n as any).x;delete (n as any).y;});graphRef.current?.d3ReheatSimulation?.();resetView();};
 return <div className="graph-preview">
  <div className="graph-grid"/>
  <div className="graph-toolbar">
   <label className="field-label">Relationship type <select value={relationshipFilter} onChange={e=>setRelationshipFilter(e.target.value)}><option value="all">All relationship types</option>{relationshipTypes.map(type=><option key={type} value={type}>{type}</option>)}</select></label>
   <div className="button-row"><button type="button" className="secondary-button" onClick={resetView}>Fit graph</button><button type="button" className="secondary-button" onClick={saveLayout}>Save layout</button><button type="button" className="secondary-button" onClick={restoreLayout}>Restore layout</button><button type="button" className="secondary-button" onClick={clearLayout}>Reset layout</button></div>
  </div>
  <div className="force-graph-shell" style={{width:'100%',height:420,overflow:'hidden',borderRadius:12}} role="region" aria-label="Interactive evidence relationship graph">
   <ForceGraph2DComponent ref={graphRef} width={graphSize.width} height={graphSize.height} graphData={graphData} backgroundColor="rgba(0,0,0,0)" nodeId="id" nodeLabel={(node:any)=>node.name+' · '+node.type} nodeColor={(node:any)=>String(node.id)===selectedId?'#f5c76b':'#86a8ff'} nodeRelSize={6} nodeVal={5} nodeCanvasObject={(node:any,ctx:any,globalScale:number)=>{const label=String(node.name||'');const fontSize=Math.max(3,12/globalScale);ctx.font=`${fontSize}px Inter, sans-serif`;ctx.textAlign='center';ctx.textBaseline='middle';ctx.fillStyle=String(node.id)===selectedId?'#f5c76b':'#b8c8e7';ctx.fillText(label,node.x,node.y+10/globalScale);}} linkColor={(link:any)=>link.verificationStatus==='verified'?'rgba(102,211,160,0.8)':link.verificationStatus==='disputed'?'rgba(255,113,113,0.8)':'rgba(130,155,190,0.45)'} linkWidth={(link:any)=>{const id=String(link.id||'');return id===selectedRelationshipId?2.5:1;}} linkDirectionalArrowLength={3} linkDirectionalArrowRelPos={1} linkLabel={(link:any)=>String(link.type||'relationship')+' · '+String(link.verificationStatus||'unverified')} onNodeClick={(node:any)=>{const found=visible.find(e=>key(e)===String(node.id));if(found)onSelect(found);}} onLinkClick={(link:any)=>setSelectedRelationshipId(String(link.id||''))} enableNodeDrag enableZoomInteraction enablePanInteraction cooldownTicks={80} d3AlphaDecay={0.035} d3VelocityDecay={0.3}/>
  </div>
  <p className="muted-copy">Drag nodes to explore connections; scroll or pinch to zoom and drag empty space to pan. Edge colours indicate recorded verification status, not proof. Node positions are saved locally only when you choose Save layout.</p>
  {selectedRelationship&&<div className="graph-inspector"><div className="section-kicker">SELECTED RELATIONSHIP</div><b>{visible.find(e=>key(e)===selectedRelationship.fromEntityId)?.name||'Unknown entity'} — {selectedRelationship.type} — {visible.find(e=>key(e)===selectedRelationship.toEntityId)?.name||'Unknown entity'}</b><p>{selectedRelationship.rationale||'No relationship rationale recorded.'}</p><small>{selectedRelationship.verificationStatus||'unverified'} · {selectedRelationship.evidenceIds?.length||0} evidence reference(s)</small></div>}
  <div className="graph-entity-list">{visible.map(e=><button type="button" key={key(e)} className={'graph-entity-option'+(key(e)===selectedId?' selected':'')} aria-pressed={key(e)===selectedId} onClick={()=>onSelect(e)}><span>{e.name}</span><small>{e.type} · {(e.evidenceIds||[]).length} evidence reference(s)</small></button>)}</div>
  <div className="graph-relationship-list"><div className="section-kicker">VISIBLE RELATIONSHIPS</div>{visibleRelations.length?visibleRelations.map((r,i)=>{const from=visible.find(e=>key(e)===r.fromEntityId);const to=visible.find(e=>key(e)===r.toEntityId);const edgeKey=key(r)||r.fromEntityId+'-'+r.toEntityId+'-'+i;return <button type="button" className={'graph-relationship-option'+(selectedRelationshipId===edgeKey?' selected':'')} aria-pressed={selectedRelationshipId===edgeKey} onClick={()=>setSelectedRelationshipId(edgeKey)} key={edgeKey}><span>{from?.name||'Unknown entity'} <b>{r.type}</b> {to?.name||'Unknown entity'}</span><small>{r.verificationStatus||'unverified'} · {r.evidenceIds?.length||0} evidence reference(s)</small></button>}):<p className="muted-copy">No relationships connect the currently visible entities.</p>}</div>
 </div>
}
function App(){ return (window.location.pathname === '/admin' || window.location.pathname === '/admin/') ? <AdminApp /> : <WorkspaceApp />; }
export default App;
